import { SettingsForm } from "@/components/aeri/settings-form";

<SettingsForm
  initialValues={{ email: user.email, productUpdates: user.productUpdates }}
  onSubmit={async (values) => saveSettings(values)}
  onValidate={(values) =>
    values.email.includes("@") ? undefined : { email: "Enter a valid email address." }
  }
/>
